		node := g.with_ctx(ctx).tags().create().set_input(input).save()!
		result := graphql.obj(node)
		return parents.map(result)
	})
	s.resolve('Mutation', 'updateTag', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		id := gql_int_id(info.arg('id'))!
		input := tag_update_input(info.arg('input'))!
		node := g.with_ctx(ctx).tags().update_one_id(id).set_input(input).save()!
		result := graphql.obj(node)
		return parents.map(result)
	})
	s.resolve('Mutation', 'deleteTag', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		id := gql_int_id(info.arg('id'))!
		g.with_ctx(ctx).tags().delete_one_id(id).exec()!
		result := graphql.Resolved(graphql.Value(id.str()))
		return parents.map(result)
	})

	// User
	s.resolve('Query', 'users', fn [g, sizes] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		found := g.with_ctx(ctx).users().graphql_args(info.args, sizes['users'])!.all()!
		result := graphql.list(found.map(graphql.obj(it)))
		return parents.map(result)
	})
	s.resolve('Query', 'usersCount', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		n := g.with_ctx(ctx).users().graphql_where(info.args)!.count()!
		return parents.map(graphql.Resolved(graphql.Value(n)))
	})
	for name in ['createdAt', 'updatedAt', 'id', 'name'] {
		s.resolve('User', name, resolve_user_field)
	}
	s.resolve('User', 'articles', fn [g, sizes] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		cg := g.with_ctx(ctx)
		p := graphql.page_args(info.args, sizes['articles'])!
		orders := article_order(info.arg('orderBy'), true)!
		where := cg.articles().graphql_where(info.args)!
		sub := where.graphql_paged(orders, p)!
		rows := parents.map((it as UserNode).user)
		loaded := cg.users().with_articles(fn [sub] (_ ArticleQuery) ArticleQuery {
			return sub
		}).nodes(rows)!
		counts := if info.selected('totalCount') {
			user_count_articles(cg, rows, where)!
		} else {
			map[string]int{}
		}
		mut out := []graphql.Resolved{cap: loaded.len}
		for n in loaded {
			page := article_page(cg, n.articles, orders, p, counts[n.user.id.str()] or {
				0
			})!
			out << graphql.obj(page)
		}
		return out
	})
	s.resolve('Mutation', 'createUser', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		input := user_create_input(info.arg('input'))!
		node := g.with_ctx(ctx).users().create().set_input(input).save()!
		result := graphql.obj(node)
		return parents.map(result)
	})
	s.resolve('Mutation', 'updateUser', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		id := gql_i64_id(info.arg('id'))!
		input := user_update_input(info.arg('input'))!
		node := g.with_ctx(ctx).users().update_one_id(id).set_input(input).save()!
		result := graphql.obj(node)
		return parents.map(result)
	})
	s.resolve('Mutation', 'deleteUser', fn [g] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		id := gql_i64_id(info.arg('id'))!
		g.with_ctx(ctx).users().delete_one_id(id).exec()!
		result := graphql.Resolved(graphql.Value(id.str()))
		return parents.map(result)
	})

	// the fields the project's .graphql files add
	s.resolve('Query', 'search', fn [r] (ctx context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
		return r.query_search(ctx, info, parents)
	})
	return s
}

// graphql_nodes returns the rows with the global ids `ids`, in order, reading
// each table's in one query: an error at the place of an id no row has.
// `types` names the table of each range (`Client.global_types`).
fn graphql_nodes(g Graph, types map[int]string, ids []graphql.Value) ![]graphql.Resolved {
	mut keys := []i64{cap: ids.len}
	mut by_table := map[string][]i64{}
	for v in ids {
		key := gql_i64_id(v) or { -1 }
		keys << key
		if key >= 0 {
			by_table[types[int(key >> 32)] or { '' }] << key
		}
	}
	mut found := map[i64]graphql.Resolved{}
	if keys_of := by_table['articles'] {
		for n in g.articles().where_id_in(keys_of).all()! {
			found[n.article.id] = graphql.obj_of('Article', n)
		}
	}
	if keys_of := by_table['comments'] {
		for n in g.comments().where_id_in(keys_of).all()! {
			found[n.comment.id] = graphql.obj_of('Comment', n)
		}
	}
	if keys_of := by_table['users'] {
		for n in g.users().where_id_in(keys_of).all()! {
			found[n.user.id] = graphql.obj_of('User', n)
		}
	}
	mut out := []graphql.Resolved{cap: ids.len}
	for i, key in keys {
		out << found[key] or {
			graphql.Resolved(graphql.FieldError{
				message: 'Could not resolve to a node with the global ID of "${ids[i].as_string()}".'
			})
		}
	}
	return out
}

// resolve_article_field resolves the columns of `Article`.
fn resolve_article_field(_ context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(article_value((it as ArticleNode).article, info.field_name)))
}

fn article_value(row models.Article, field string) graphql.Value {
	return match field {
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		'updatedAt' { graphql.Value(row.updated_at.format_rfc3339()) }
		'id' { graphql.Value(row.id.str()) }
		'userID' { graphql.Value(row.user_id.str()) }
		'title' { graphql.Value(string(row.title)) }
		'status' { graphql.Value(row.status.str().to_upper()) }
		'views' { graphql.Value(int(row.views)) }
		'deletedAt' {
			if v := row.deleted_at { graphql.Value(v.format_rfc3339()) } else { graphql.null }
		}
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `Article` list.
fn (q ArticleQuery) graphql_where(args map[string]graphql.Value) !ArticleQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...article_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `Article` list: `where`, `orderBy`,
// and `limit` and `offset`, bounded by `size`.
fn (q ArticleQuery) graphql_args(args map[string]graphql.Value, size graphql.PageSize) !ArticleQuery {
	page := graphql.list_args(args, size)!
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := article_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := page.limit {
		next = next.limit(limit)
	}
	if offset := page.offset {
		next = next.offset(offset)
	}
	return next
}

// article_order returns the orders of an `orderBy` of `Article`, and with `with_key`,
// the key last, unless it orders by it already.
fn article_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'CREATED_AT' {
				orders << load.Order{ column: 'Stamps.created_at', desc: desc, typ: 'time.Time' }
			}
			'UPDATED_AT' {
				orders << load.Order{ column: 'Stamps.updated_at', desc: desc, typ: 'time.Time' }
			}
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'i64' }
				keyed = true
			}
			'USER_ID' {
				orders << load.Order{ column: 'user_id', desc: desc, typ: 'i64' }
			}
			'TITLE' {
				orders << load.Order{ column: 'title', desc: desc, typ: 'string' }
			}
			'STATUS' {
				orders << load.Order{ column: 'status', desc: desc, typ: 'enum' }
			}
			'VIEWS' {
				orders << load.Order{ column: 'views', desc: desc, typ: 'int' }
			}
			'DELETED_AT' {
				orders << load.Order{ column: 'deleted_at', desc: desc, typ: '?time.Time' }
			}
			'COMMENTS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "comments" AS "t1" WHERE "t1"."article_id" = "t0"."id")', desc: desc, typ: 'int' }
			}
			'TAGS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "article_tags" AS "t1" WHERE "t1"."article_id" = "t0"."id")', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a ArticleOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'i64'
		}
	}
	return orders
}

// article_where returns the conditions of a `ArticleWhereInput`.
fn article_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'not' {
				conds << load.not(load.and(...article_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << article_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...article_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'createdAt' { conds << load.eq('Stamps.created_at', gql_time(v)!) }
			'createdAtNEQ' { conds << load.ne('Stamps.created_at', gql_time(v)!) }
			'createdAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.created_at', it)))
			}
			'createdAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.created_at', it)))
			}
			'createdAtGT' { conds << load.gt('Stamps.created_at', gql_time(v)!) }
			'createdAtGTE' { conds << load.ge('Stamps.created_at', gql_time(v)!) }
			'createdAtLT' { conds << load.lt('Stamps.created_at', gql_time(v)!) }
			'createdAtLTE' { conds << load.le('Stamps.created_at', gql_time(v)!) }
			'updatedAt' { conds << load.eq('Stamps.updated_at', gql_time(v)!) }
			'updatedAtNEQ' { conds << load.ne('Stamps.updated_at', gql_time(v)!) }
			'updatedAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.updated_at', it)))
			}
			'updatedAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.updated_at', it)))
			}
			'updatedAtGT' { conds << load.gt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtGTE' { conds << load.ge('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLT' { conds << load.lt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLTE' { conds << load.le('Stamps.updated_at', gql_time(v)!) }
			'id' { conds << load.eq('id', gql_i64_id(v)!) }
			'idNEQ' { conds << load.ne('id', gql_i64_id(v)!) }
			'idIn' { conds << load.in_i64s('id', gql_i64s(v)!) }
			'idNotIn' { conds << load.not_in_i64s('id', gql_i64s(v)!) }
			'idGT' { conds << load.gt('id', gql_i64_id(v)!) }
			'idGTE' { conds << load.ge('id', gql_i64_id(v)!) }
			'idLT' { conds << load.lt('id', gql_i64_id(v)!) }
			'idLTE' { conds << load.le('id', gql_i64_id(v)!) }
			'userID' { conds << load.eq('user_id', gql_i64_id(v)!) }
			'userIDNEQ' { conds << load.ne('user_id', gql_i64_id(v)!) }
			'userIDIn' { conds << load.in_i64s('user_id', gql_i64s(v)!) }
			'userIDNotIn' { conds << load.not_in_i64s('user_id', gql_i64s(v)!) }
			'title' { conds << load.eq('title', v.as_string()) }
			'titleNEQ' { conds << load.ne('title', v.as_string()) }
			'titleIn' { conds << load.in_strings('title', gql_strings(v)) }
			'titleNotIn' { conds << load.not_in_strings('title', gql_strings(v)) }
			'titleGT' { conds << load.gt('title', v.as_string()) }
			'titleGTE' { conds << load.ge('title', v.as_string()) }
			'titleLT' { conds << load.lt('title', v.as_string()) }
			'titleLTE' { conds << load.le('title', v.as_string()) }
			'titleContains' { conds << load.contains('title', v.as_string()) }
			'titleHasPrefix' { conds << load.has_prefix('title', v.as_string()) }
			'titleHasSuffix' { conds << load.has_suffix('title', v.as_string()) }
			'titleEqualFold' { conds << load.equal_fold('title', v.as_string()) }
			'titleContainsFold' { conds << load.contains_fold('title', v.as_string()) }
			'status' { conds << load.eq('status', status_enum(v.as_string())!) }
			'statusNEQ' { conds << load.ne('status', status_enum(v.as_string())!) }
			'statusIn' { conds << load.in_ints('status', status_enums(v)!) }
			'statusNotIn' { conds << load.not_in_ints('status', status_enums(v)!) }
			'views' { conds << load.eq('views', v.as_int()) }
			'viewsNEQ' { conds << load.ne('views', v.as_int()) }
			'viewsIn' { conds << load.in_ints('views', gql_ints(v)) }
			'viewsNotIn' { conds << load.not_in_ints('views', gql_ints(v)) }
			'viewsGT' { conds << load.gt('views', v.as_int()) }
			'viewsGTE' { conds << load.ge('views', v.as_int()) }
			'viewsLT' { conds << load.lt('views', v.as_int()) }
			'viewsLTE' { conds << load.le('views', v.as_int()) }
			'deletedAt' { conds << load.eq('deleted_at', gql_time(v)!) }
			'deletedAtNEQ' { conds << load.ne('deleted_at', gql_time(v)!) }
			'deletedAtIn' { conds << load.or(...gql_times(v)!.map(load.eq('deleted_at', it))) }
			'deletedAtNotIn' { conds << load.and(...gql_times(v)!.map(load.ne('deleted_at', it))) }
			'deletedAtGT' { conds << load.gt('deleted_at', gql_time(v)!) }
			'deletedAtGTE' { conds << load.ge('deleted_at', gql_time(v)!) }
			'deletedAtLT' { conds << load.lt('deleted_at', gql_time(v)!) }
			'deletedAtLTE' { conds << load.le('deleted_at', gql_time(v)!) }
			'deletedAtIsNil' {
				conds << if v.as_bool() {
					load.is_null('deleted_at')
				} else {
					load.is_not_null('deleted_at')
				}
			}
			'deletedAtNotNil' {
				conds << if v.as_bool() {
					load.is_not_null('deleted_at')
				} else {
					load.is_null('deleted_at')
				}
			}
			'hasAuthor' {
				conds << if v.as_bool() {
					article_has_author()
				} else {
					load.not(article_has_author())
				}
			}
			'hasAuthorWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << user_where(item.as_map())!
				}
				conds << article_has_author_with(...all)
			}
			'hasComments' {
				conds << if v.as_bool() {
					article_has_comments()
				} else {
					load.not(article_has_comments())
				}
			}
			'hasCommentsWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << comment_where(item.as_map())!
				}
				conds << article_has_comments_with(...all)
			}
			'hasTags' {
				conds << if v.as_bool() { article_has_tags() } else { load.not(article_has_tags()) }
			}
			'hasTagsWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << tag_where(item.as_map())!
				}
				conds << article_has_tags_with(...all)
			}
			else {}
		}
	}
	return conds
}

// status_enum returns the value of `models.Status` a GraphQL enum value names.
fn status_enum(name string) !int {
	return match name {
		'DRAFT' { int(models.Status.draft) }
		'PUBLISHED' { int(models.Status.published) }
		'ARCHIVED' { int(models.Status.archived) }
		else { error('`${name}` is not a Status') }
	}
}

// status_enums returns the values of `models.Status` that a list of GraphQL enum values
// names.
fn status_enums(v graphql.Value) ![]int {
	mut out := []int{}
	for item in v.as_list() {
		out << status_enum(item.as_string())!
	}
	return out
}

// article_connection returns the page of `q` that a `ArticleConnection`'s arguments
// ask for, bounded by `size`, and how many rows `q` matches when `totalCount`
// is asked for.
fn article_connection(q ArticleQuery, info graphql.FieldInfo, size graphql.PageSize) !graphql.Connection {
	p := graphql.page_args(info.args, size)!
	orders := article_order(info.arg('orderBy'), true)!
	rows := q.graphql_paged(orders, p)!.all()!
	total := if info.selected('totalCount') { q.count()! } else { 0 }
	return article_page(q.graph, rows, orders, p, total)
}

// graphql_paged returns `q` in `orders`, which end with the key (reversed for
// `last`), past the cursors of `p`, and limited to one row past the page.
fn (q ArticleQuery) graphql_paged(orders []load.Order, p graphql.PageArgs) !ArticleQuery {
	types := orders.map(it.typ)
	nulls := load.nulls_largest(q.graph.client.conn)
	mut conds := q.query.conds.clone()
	if c := p.after {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, true, nulls)!
	}
	if c := p.before {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, false, nulls)!
	}
	backward := p.last != none
	mut next := q
	next.query = load.Query{
		...q.query
		conds:  conds
		order:  ''
		desc:   false
		orders: if backward { orders.map(load.Order{ ...it, desc: !it.desc }) } else { orders }
		limit:  if c := p.first {
			c + 1
		} else if c := p.last {
			c + 1
		} else {
			0
		}
		offset: 0
	}
	return next
}

// article_page returns `nodes`, read in `orders` (reversed for `last`) and one row
// past the page, as a connection.
fn article_page(g Graph, nodes []ArticleNode, orders []load.Order, p graphql.PageArgs, total int) !graphql.Connection {
	mut page := nodes.clone()
	mut has_next := false
	mut has_previous := false
	if count := p.first {
		if page.len > count {
			has_next = true
			page = page[..count].clone()
		}
	} else if count := p.last {
		if page.len > count {
			has_previous = true
			page = page[..count].clone()
		}
		page.reverse_in_place()
	}
	cursors := article_cursors(g, page.map(it.article), orders)!
	return graphql.connection(page.map(graphql.Source(it)), cursors, has_next, has_previous, total)
}

// article_cursors returns the cursors of `rows`: the values of their order
// columns, those of edges read in one query.
fn article_cursors(g Graph, rows []models.Article, orders []load.Order) ![]string {
	exprs := load.expr_values(g.client.conn, 'articles', 'id', .i64,
		rows.map(it.id.str()), orders)!
	mut out := []string{cap: rows.len}
	for row in rows {
		from_exprs := exprs[row.id.str()] or { []orm.Primitive{} }
		mut values := []orm.Primitive{cap: orders.len}
		for i, o in orders {
			values << if o.expr != '' {
				from_exprs[i] or { orm.Primitive(orm.Null{}) }
			} else {
				article_order_value(row, o.column)
			}
		}
		out << load.encode_cursor(values)
	}
	return out
}

// article_order_value returns a column of a `articles` row, for a cursor.
fn article_order_value(row models.Article, column string) orm.Primitive {
	return match column {
		'Stamps.created_at' { orm.Primitive(row.created_at) }
		'Stamps.updated_at' { orm.Primitive(row.updated_at) }
		'id' { orm.Primitive(row.id) }
		'user_id' { orm.Primitive(row.user_id) }
		'title' { orm.Primitive(row.title) }
		'status' { orm.Primitive(int(row.status)) }
		'views' { orm.Primitive(row.views) }
		'deleted_at' {
			if v := row.deleted_at { orm.Primitive(v) } else { orm.Primitive(orm.Null{}) }
		}
		else { orm.Primitive(orm.Null{}) }
	}
}

// article_create_input reads the input of `createArticle`.
fn article_create_input(value graphql.Value) !CreateArticleInput {
	mut input := CreateArticleInput{}
	for name, v in value.as_map() {
		if v is graphql.Null {
			continue
		}
		match name {
			'createdAt' {
				input.created_at = gql_time(v)!
			}
			'updatedAt' {
				input.updated_at = gql_time(v)!
			}
			'userID' {
