		}
		match key {
			'not' {
				conds << load.not(load.and(...user_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << user_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...user_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'createdAt' { conds << load.eq('Stamps.created_at', gql_time(v)!) }
			'createdAtNEQ' { conds << load.ne('Stamps.created_at', gql_time(v)!) }
			'createdAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.created_at', it)))
			}
			'createdAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.created_at', it)))
			}
			'createdAtGT' { conds << load.gt('Stamps.created_at', gql_time(v)!) }
			'createdAtGTE' { conds << load.ge('Stamps.created_at', gql_time(v)!) }
			'createdAtLT' { conds << load.lt('Stamps.created_at', gql_time(v)!) }
			'createdAtLTE' { conds << load.le('Stamps.created_at', gql_time(v)!) }
			'updatedAt' { conds << load.eq('Stamps.updated_at', gql_time(v)!) }
			'updatedAtNEQ' { conds << load.ne('Stamps.updated_at', gql_time(v)!) }
			'updatedAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.updated_at', it)))
			}
			'updatedAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.updated_at', it)))
			}
			'updatedAtGT' { conds << load.gt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtGTE' { conds << load.ge('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLT' { conds << load.lt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLTE' { conds << load.le('Stamps.updated_at', gql_time(v)!) }
			'id' { conds << load.eq('id', gql_i64_id(v)!) }
			'idNEQ' { conds << load.ne('id', gql_i64_id(v)!) }
			'idIn' { conds << load.in_i64s('id', gql_i64s(v)!) }
			'idNotIn' { conds << load.not_in_i64s('id', gql_i64s(v)!) }
			'idGT' { conds << load.gt('id', gql_i64_id(v)!) }
			'idGTE' { conds << load.ge('id', gql_i64_id(v)!) }
			'idLT' { conds << load.lt('id', gql_i64_id(v)!) }
			'idLTE' { conds << load.le('id', gql_i64_id(v)!) }
			'name' { conds << load.eq('name', v.as_string()) }
			'nameNEQ' { conds << load.ne('name', v.as_string()) }
			'nameIn' { conds << load.in_strings('name', gql_strings(v)) }
			'nameNotIn' { conds << load.not_in_strings('name', gql_strings(v)) }
			'nameGT' { conds << load.gt('name', v.as_string()) }
			'nameGTE' { conds << load.ge('name', v.as_string()) }
			'nameLT' { conds << load.lt('name', v.as_string()) }
			'nameLTE' { conds << load.le('name', v.as_string()) }
			'nameContains' { conds << load.contains('name', v.as_string()) }
			'nameHasPrefix' { conds << load.has_prefix('name', v.as_string()) }
			'nameHasSuffix' { conds << load.has_suffix('name', v.as_string()) }
			'nameEqualFold' { conds << load.equal_fold('name', v.as_string()) }
			'nameContainsFold' { conds << load.contains_fold('name', v.as_string()) }
			'hasArticles' {
				conds << if v.as_bool() {
					user_has_articles()
				} else {
					load.not(user_has_articles())
				}
			}
			'hasArticlesWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << article_where(item.as_map())!
				}
				conds << user_has_articles_with(...all)
			}
			else {}
		}
	}
	return conds
}

// user_count_articles counts the `articles` of each of `rows` that `sub` keeps, by the
// row's key.
fn user_count_articles(g Graph, rows []models.User, sub ArticleQuery) !map[string]int {
	conds := g.client.prepare_edge_query('articles', sub.query)!.conds
	return load.count_each(g.client.conn, 'articles', 'user_id', rows.map(it.id.str()),
		.i64, load.Query{
			conds: conds
		})
}

// user_create_input reads the input of `createUser`.
fn user_create_input(value graphql.Value) !CreateUserInput {
	mut input := CreateUserInput{}
	for name, v in value.as_map() {
		if v is graphql.Null {
			continue
		}
		match name {
			'createdAt' {
				input.created_at = gql_time(v)!
			}
			'updatedAt' {
				input.updated_at = gql_time(v)!
			}
			'name' {
				input.name = v.as_string()
			}
			'email' {
				input.email = v.as_string()
			}
			'articleIDs' {
				input.article_ids = gql_i64s(v)!
			}
			else {}
		}
	}
	return input
}

// user_update_input reads the input of `updateUser`.
fn user_update_input(value graphql.Value) !UpdateUserInput {
	mut input := UpdateUserInput{}
	for name, v in value.as_map() {
		if v is graphql.Null {
			continue
		}
		match name {
			'updatedAt' {
				input.updated_at = gql_time(v)!
			}
			'name' {
				input.name = v.as_string()
			}
			'email' {
				input.email = v.as_string()
			}
			'addArticleIDs' {
				input.add_article_ids = gql_i64s(v)!
			}
			'removeArticleIDs' {
				input.remove_article_ids = gql_i64s(v)!
			}
			'clearArticles' {
				input.clear_articles = v.as_bool()
			}
			else {}
		}
	}
	return input
}

// gql_int_id reads an int key from an ID.
fn gql_int_id(v graphql.Value) !int {
	s := v.as_string()
	n := s.int()
	if n.str() != s {
		return error('invalid ID "${s}"')
	}
	return n
}

fn gql_int_ids(v graphql.Value) ![]int {
	mut out := []int{}
	for item in v.as_list() {
		out << gql_int_id(item)!
	}
	return out
}

// gql_i64_id reads an i64 key from an ID.
fn gql_i64_id(v graphql.Value) !i64 {
	s := v.as_string()
	n := s.i64()
	if n.str() != s {
		return error('invalid ID "${s}"')
	}
	return n
}

fn gql_i64s(v graphql.Value) ![]i64 {
	mut out := []i64{}
	for item in v.as_list() {
		out << if item is string { gql_i64_id(item)! } else { i64(item.as_float()) }
	}
	return out
}

fn gql_ints(v graphql.Value) []int {
	return v.as_list().map(it.as_int())
}

fn gql_strings(v graphql.Value) []string {
	return v.as_list().map(it.as_string())
}

fn gql_times(v graphql.Value) ![]time.Time {
	mut out := []time.Time{}
	for item in v.as_list() {
		out << gql_time(item)!
	}
	return out
}

// gql_time reads a Time.
fn gql_time(v graphql.Value) !time.Time {
	return time.parse_rfc3339(v.as_string()) or {
		return error('invalid Time "${v.as_string()}": use RFC 3339, such as 2026-10-13T07:30:00Z')
	}
}

// time_scalar checks Time values: RFC 3339 strings.
const time_scalar = graphql.Scalar{
	parse_value:   fn (v graphql.Value) !graphql.Value {
		if v !is string {
			return error('Time must be an RFC 3339 string')
		}
		gql_time(v)!
		return v
	}
	parse_literal: fn (node graphql.ValueNode, _ map[string]graphql.Value) !graphql.Value {
		if node is graphql.StringValue {
			gql_time(graphql.Value(node.value))!
			return graphql.Value(node.value)
		}
		return error('Time must be an RFC 3339 string')
	}
}
